import React, { useState } from 'react';

const QuanLyThongBao = () => {
    const [history] = useState([
        { id: 1, tieuDe: 'Thông báo cắt nước định kỳ', ngay: '15/04/2026', nguoiGui: 'Ban Quản Lý' },
        { id: 2, tieuDe: 'Nhắc nhở đóng phí dịch vụ tháng 4', ngay: '10/04/2026', nguoiGui: 'Kế toán' },
    ]);

    return (
        <div style={styles.container}>
            <div style={styles.formSection}>
                <h2>🔔 Tạo thông báo mới</h2>
                <input type="text" placeholder="Tiêu đề thông báo..." style={styles.input} />
                <textarea placeholder="Nội dung chi tiết gửi đến cư dân..." style={styles.textarea} />
                <button style={styles.sendBtn}>🚀 Gửi cho cư dân</button>
            </div>

            <div style={styles.historySection}>
                <h3>Lịch sử thông báo đã gửi</h3>
                {history.map(item => (
                    <div key={item.id} style={styles.historyItem}>
                        <div>
                            <strong>{item.tieuDe}</strong>
                            <p style={{fontSize: '12px', color: '#888'}}>Ngày gửi: {item.ngay} | Người gửi: {item.nguoiGui}</p>
                        </div>
                        <button style={styles.viewBtn}>Xem lại</button>
                    </div>
                ))}
            </div>
        </div>
    );
};

const styles = {
    container: { display: 'flex', flexDirection: 'column', gap: '30px' },
    formSection: { backgroundColor: '#fff', padding: '25px', borderRadius: '12px', display: 'flex', flexDirection: 'column', gap: '15px' },
    input: { padding: '12px', borderRadius: '8px', border: '1px solid #ddd', fontSize: '16px' },
    textarea: { padding: '12px', borderRadius: '8px', border: '1px solid #ddd', minHeight: '120px', fontSize: '14px' },
    sendBtn: { backgroundColor: '#2e7d32', color: '#fff', padding: '12px', border: 'none', borderRadius: '8px', cursor: 'pointer', fontWeight: 'bold' },
    historySection: { backgroundColor: '#fff', padding: '20px', borderRadius: '12px' },
    historyItem: { display: 'flex', justifyContent: 'space-between', padding: '15px 0', borderBottom: '1px solid #eee' },
    viewBtn: { backgroundColor: '#eee', border: 'none', padding: '5px 10px', borderRadius: '4px', cursor: 'pointer' }
};

export default QuanLyThongBao;
